// Enhanced Command Parser with validation and error handling
const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;

  // Extract message text from different platforms
  let messageText = '';
  let senderId = '';
  let senderPhone = '';
  let channelType = '';
  let chatId = '';

  // TELEGRAM DETECTION
  if (data.message && data.message.from) {
    channelType = 'telegram';
    messageText = data.message.text || '';
    senderId = data.message.from.id ? data.message.from.id.toString() : '';
    chatId = data.message.chat.id ? data.message.chat.id.toString() : '';
    senderPhone = data.message.from.phone_number || null;
  }
  // WHATSAPP DETECTION
  else if (data.from && data.text && data.text.body) {
    channelType = 'whatsapp';
    messageText = data.text.body;
    senderPhone = data.from;
    senderId = senderPhone;
  }
  // FALLBACK: WhatsApp alternative structure
  else if (data.message && data.message.from && !data.message.chat) {
    channelType = 'whatsapp';
    messageText = data.message.text || '';
    senderPhone = data.message.from;
    senderId = senderPhone;
  }
  // WEBHOOK FROM MESSAGE ROUTER
  else if (data.sender_id && data.message) {
    channelType = data.channel || 'telegram';
    messageText = data.message;
    senderId = data.sender_id;
    chatId = data.sender_id;
    senderPhone = null;
  }

  // Parse command
  const text = messageText.trim();
  const command = text.toLowerCase();

  // Handle /availability command with parameters
  if (command.startsWith('/availability ')) {
    const parts = command.split(/\s+/);

    if (parts.length !== 4) {
      results.push({
        json: {
          error: true,
          error_type: 'invalid_format',
          message: '❌ *Invalid Format*\n\nCorrect usage:\n`/availability PropertyName YYYY-MM-DD YYYY-MM-DD`\n\nExample:\n`/availability Villa2024 2025-03-15 2025-03-20`',
          channel_type: channelType,
          sender_id: senderId,
          sender_phone: senderPhone,
          chat_id: chatId
        }
      });
      continue;
    }

    // Validate date format
    const propertyName = parts[1];
    const checkIn = parts[2];
    const checkOut = parts[3];
    const dateRegex = /^\d{4}-\d{2}-\d{2}$/;

    if (!dateRegex.test(checkIn) || !dateRegex.test(checkOut)) {
      results.push({
        json: {
          error: true,
          error_type: 'invalid_date',
          message: '❌ *Invalid Date Format*\n\nDates must be in YYYY-MM-DD format\n\nExample:\n`/availability Villa2024 2025-03-15 2025-03-20`',
          channel_type: channelType,
          sender_id: senderId,
          sender_phone: senderPhone,
          chat_id: chatId
        }
      });
      continue;
    }

    // Validate check-out is after check-in
    if (new Date(checkOut) <= new Date(checkIn)) {
      results.push({
        json: {
          error: true,
          error_type: 'invalid_date_range',
          message: '❌ *Invalid Date Range*\n\nCheck-out date must be after check-in date',
          channel_type: channelType,
          sender_id: senderId,
          sender_phone: senderPhone,
          chat_id: chatId
        }
      });
      continue;
    }

    results.push({
      json: {
        command: 'availability',
        property_name: propertyName,
        check_in: checkIn,
        check_out: checkOut,
        channel_type: channelType,
        sender_id: senderId,
        sender_phone: senderPhone,
        chat_id: chatId,
        original_message: messageText
      }
    });
    continue;
  }

  // Handle standard commands
  const validCommands = ['dashboard', 'deals', 'tasks', 'bookings', 'help'];
  const cleanCommand = command.replace('/', '').trim();

  if (!command.startsWith('/') || !validCommands.includes(cleanCommand)) {
    results.push({
      json: {
        error: true,
        error_type: 'unknown_command',
        message: '❓ *Unknown Command*\n\nAvailable commands:\n• /dashboard\n• /deals\n• /tasks\n• /bookings\n• /availability\n• /help\n\nType /help for more details.',
        channel_type: channelType,
        sender_id: senderId,
        sender_phone: senderPhone,
        chat_id: chatId
      }
    });
    continue;
  }

  results.push({
    json: {
      command: cleanCommand,
      channel_type: channelType,
      sender_id: senderId,
      sender_phone: senderPhone,
      chat_id: chatId,
      original_message: messageText
    }
  });
}

return results;

// Professional Dashboard Message Formatter
const commandData = $('Route by Command').first().json;
const tasks = $('Query Control Panel Tasks').all();
const deals = $('Query Deals for Dashboard').all();
const bookings = $('Query Bookings for Dashboard').all();

// Count active bookings (currently staying)
const now = new Date();
const activeBookings = bookings.filter(b => {
  const checkIn = new Date(b.json.check_in_date);
  const checkOut = new Date(b.json.check_out_date);
  return now >= checkIn && now <= checkOut;
}).length;

// Count upcoming bookings (next 7 days)
const nextWeek = new Date();
nextWeek.setDate(nextWeek.getDate() + 7);
const upcomingBookings = bookings.filter(b => {
  const checkIn = new Date(b.json.check_in_date);
  return checkIn > now && checkIn <= nextWeek;
}).length;

