// Format Tasks List with priority handling
const commandData = $('Route by Command').first().json;
const tasks = $input.all();

if (tasks.length === 0) {
  const message = `✅ *NO PENDING TASKS*
━━━━━━━━━━━━━━━━━━━━

Great job! You're all caught up with your tasks.

━━━━━━━━━━━━━━━━━━━━`;

  const keyboard = {
    inline_keyboard: [
      [{text: '🏡 Back to Dashboard', callback_data: 'dashboard'}]
    ]
  };

  return [{
    json: {
      message: message,
      keyboard: keyboard,
      channel_type: commandData.channel_type,
      sender_id: commandData.sender_id,
      sender_phone: commandData.sender_phone,
      chat_id: commandData.chat_id,
      parse_mode: 'Markdown'
    }
  }];
}

// Sort tasks by priority and due date
const sortedTasks = tasks.sort((a, b) => {
  const priorityOrder = {high: 1, medium: 2, low: 3};
  const aPriority = priorityOrder[a.json.priority?.toLowerCase()] || 4;
  const bPriority = priorityOrder[b.json.priority?.toLowerCase()] || 4;

  if (aPriority !== bPriority) return aPriority - bPriority;

  const aDate = new Date(a.json.due_date || '9999-12-31');
  const bDate = new Date(b.json.due_date || '9999-12-31');
  return aDate - bDate;
});

// Format message
let message = `✅ *PENDING TASKS*
━━━━━━━━━━━━━━━━━━━━

`;

const keyboard = { inline_keyboard: [] };

sortedTasks.forEach((task, index) => {
  const t = task.json;
  const taskNum = index + 1;
  const priorityEmoji = {
    high: '🔴',
    medium: '🟡',
    low: '🟢'
  }[t.priority?.toLowerCase()] || '⚪';

  message += `${priorityEmoji} *${taskNum}. ${t.task_name || 'Unnamed Task'}*
`;
  message += `   📋 ${t.task_description || 'No description'}
`;
  message += `   📅 Due: ${t.due_date || 'No deadline'}
`;
  message += `   🏷️ Priority: ${t.priority || 'normal'}
`;
  message += `
`;

  // Add action buttons
  keyboard.inline_keyboard.push([
    {text: `✓ Complete #${taskNum}`, callback_data: `complete_task_${t.task_id}`}
  ]);

  keyboard.inline_keyboard.push([
    {text: `⏰ Snooze #${taskNum}`, callback_data: `snooze_task_${t.task_id}`},
    {text: `📄 Details #${taskNum}`, callback_data: `view_task_${t.task_id}`}
  ]);
});

message += `━━━━━━━━━━━━━━━━━━━━
Total: ${sortedTasks.length} task${sortedTasks.length !== 1 ? 's' : ''} pending`;

// Add back button
keyboard.inline_keyboard.push([
  {text: '🏡 Back to Dashboard', callback_data: 'dashboard'}
]);

return [{
  json: {
    message: message,
    keyboard: keyboard,
    channel_type: commandData.channel_type,
    sender_id: commandData.sender_id,
    sender_phone: commandData.sender_phone,
    chat_id: commandData.chat_id,
    parse_mode: 'Markdown'
  }
}];

// Format Bookings Calendar with date filtering
const commandData = $('Route by Command').first().json;
const bookings = $input.all();

if (bookings.length === 0) {
  const message = `📅 *NO UPCOMING BOOKINGS*
━━━━━━━━━━━━━━━━━━━━

No confirmed bookings in the next 30 days.

━━━━━━━━━━━━━━━━━━━━`;

  const keyboard = {
    inline_keyboard: [
      [{text: '🏡 Back to Dashboard', callback_data: 'dashboard'}]
    ]
  };

  return [{
    json: {
      message: message,
      keyboard: keyboard,
      channel_type: commandData.channel_type,
      sender_id: commandData.sender_id,
      sender_phone: commandData.sender_phone,
      chat_id: commandData.chat_id,
      parse_mode: 'Markdown'
    }
  }];
}

// Filter and sort bookings (next 30 days)
const now = new Date();
const next30Days = new Date();
next30Days.setDate(next30Days.getDate() + 30);

const relevantBookings = bookings
  .filter(b => {
    const checkIn = new Date(b.json.check_in_date);
    return checkIn >= now && checkIn <= next30Days;
  })
  .sort((a, b) => {
    return new Date(a.json.check_in_date) - new Date(b.json.check_in_date);
  });

// Format message
let message = `📅 *UPCOMING BOOKINGS*
━━━━━━━━━━━━━━━━━━━━
Next 30 Days

`;

const keyboard = { inline_keyboard: [] };

relevantBookings.forEach((booking, index) => {
  const b = booking.json;
  const bookingNum = index + 1;

  // Calculate days until check-in
  const checkIn = new Date(b.check_in_date);
  const daysUntil = Math.ceil((checkIn - now) / (1000 * 60 * 60 * 24));
  const urgencyEmoji = daysUntil <= 3 ? '🔴' : daysUntil <= 7 ? '🟡' : '🟢';

  message += `${urgencyEmoji} *${bookingNum}. ${b.property_name || 'Property'}*
`;
  message += `   👤 Guest: ${b.guest_name || 'Unknown'}
`;
  message += `   📆 Check-in: ${b.check_in_date} (${daysUntil}d)
`;
  message += `   📆 Check-out: ${b.check_out_date}
`;
  message += `   💰 Amount: $${b.total_amount || '0'}
`;
  message += `
`;

  // Add action buttons
  keyboard.inline_keyboard.push([
    {text: `📋 Details #${bookingNum}`, callback_data: `view_booking_${b.booking_id}`},
    {text: `💬 Contact #${bookingNum}`, callback_data: `contact_guest_${b.booking_id}`}
  ]);
});

message += `━━━━━━━━━━━━━━━━━━━━
Total: ${relevantBookings.length} booking${relevantBookings.length !== 1 ? 's' : ''} in next 30 days`;

// Add back button
keyboard.inline_keyboard.push([
  {text: '🏡 Back to Dashboard', callback_data: 'dashboard'}
]);

return [{
  json: {
    message: message,
    keyboard: keyboard,
    channel_type: commandData.channel_type,
    sender_id: commandData.sender_id,
    sender_phone: commandData.sender_phone,
    chat_id: commandData.chat_id,
    parse_mode: 'Markdown'
  }
}];

// Format Availability Results with detailed info
const commandData = $('Route by Command').first().json;
const webhookResponse = $input.first().json;

let message = '';
let keyboard = { inline_keyboard: [] };

if (webhookResponse.available === true) {
  const nights = Math.ceil(
    (new Date(webhookResponse.check_out) - new Date(webhookResponse.check_in)) / 
    (1000 * 60 * 60 * 24)
  );

  message = `✅ *PROPERTY AVAILABLE*
━━━━━━━━━━━━━━━━━━━━

`;
  message += `🏡 Property: ${commandData.property_name}
`;
  message += `📅 Check-in: ${commandData.check_in}
`;
  message += `📅 Check-out: ${commandData.check_out}
`;
  message += `🌙 Nights: ${nights}
`;

  if (webhookResponse.price) {
    message += `💰 Price: $${webhookResponse.price}
`;
  }

  message += `
✅ *The property is available for these dates!*`;

  keyboard.inline_keyboard.push([
    {text: '✓ Create Booking', callback_data: `create_booking_${commandData.property_name}`}
  ]);
} else if (webhookResponse.available === false) {
  message = `❌ *PROPERTY NOT AVAILABLE*
━━━━━━━━━━━━━━━━━━━━

`;
  message += `🏡 Property: ${commandData.property_name}
`;
  message += `📅 Check-in: ${commandData.check_in}
`;
  message += `📅 Check-out: ${commandData.check_out}
`;
  message += `
❌ *Sorry, not available for these dates.*`;

  if (webhookResponse.reason) {
    message += `

📝 Reason: ${webhookResponse.reason}`;
  }

  if (webhookResponse.conflicting_bookings) {
    message += `

⚠️ Conflicting bookings found.`;
  }
} else {
  message = `⚠️ *ERROR CHECKING AVAILABILITY*
━━━━━━━━━━━━━━━━━━━━

`;

  if (webhookResponse.error) {
    message += `Error: ${webhookResponse.error}
`;
  } else {
    message += `Unable to check availability. Please try again.
`;
  }
}

message += `
━━━━━━━━━━━━━━━━━━━━`;

// Add back button
keyboard.inline_keyboard.push([
  {text: '🏡 Back to Dashboard', callback_data: 'dashboard'}
]);

return [{
  json: {
    message: message,
    keyboard: keyboard,
    channel_type: commandData.channel_type,
    sender_id: commandData.sender_id,
    sender_phone: commandData.sender_phone,
    chat_id: commandData.chat_id,
    parse_mode: 'Markdown'
  }
}];

// Convert Telegram inline keyboard to WhatsApp buttons format
const data = $input.first().json;

// WhatsApp supports maximum 3 buttons per message
// Take first 3 buttons from inline keyboard
const buttons = [];

if (data.keyboard && data.keyboard.inline_keyboard) {
  data.keyboard.inline_keyboard.slice(0, 3).forEach(row => {
    if (row[0]) {
      buttons.push({
        type: 'reply',
        reply: {
          id: row[0].callback_data,
          title: row[0].text.substring(0, 20) // WhatsApp max 20 chars
        }
      });
    }
  });
}

return [{
  json: {
    to: data.sender_phone,
    body: data.message,
    buttons: buttons
  }
}];
